</head>
<body>

    <header>
        <div class="nav-container">
            <a href="index.html" class="logo">家味餐厅</a>
            <ul class="nav-links">
                <li><a href="index.html">首页</a></li>
                <li><a href="menu.html">菜单</a></li>
                <li><a href="about.html">关于我们</a></li>
                <li><a href="reservation.html" class="active">预订座位</a></li>
            </ul>
        </div>
    </header>

    <main>
        <h2 style="text-align: center; margin-bottom: 40px;">预订您的席位</h2>

        <div class="booking-layout">
            <form class="form-container" id="reservationForm">
                <div class="form-group">
                    <label for="name">您的姓名</label>
                    <input type="text" id="name" required placeholder="请输入真实姓名">
                </div>
                <div class="form-group">
                    <label for="phone">联系电话</label>
                    <input type="tel" id="phone" required placeholder="请输入手机号码">
                </div>
                <div class="form-group">
                    <label for="date">用餐日期</label>
                    <input type="date" id="date" required>
                </div>
                <div class="form-group">
                    <label for="time">用餐时间</label>
                    <select id="time" required>
                        <option value="">请选择时间</option>
                        <option value="10:00">10:00 - 11:30</option>
                        <option value="11:30">11:30 - 13:00</option>
                        <option value="11:45">11:45 - 13:15</option>
                        <option value="17:30">17:30 - 19:00</option>
                        <option value="19:00">19:00 - 20:30</option>
                        <option value="20:00">20:00 - 21:30</option>
                    </select>
                </div>
                <div class="form-group">
                    <label for="guests">人数</label>
                    <select id="guests" required>
                        <option value="2">2人</option>
                        <option value="3">3人</option>
                        <option value="4" selected>4人</option>
                        <option value="5">5人</option>
                        <option value="6">6人</option>
                        <option value="7">7人 (含包厢)</option>
                        <option value="8">8人 (含包厢)</option>
                    </select>
                </div>
                <div class="form-group">
                    <label for="note">备注需求</label>
                    <textarea id="note" rows="3" placeholder="是否有过敏源或特殊要求？"></textarea>
                </div>
                <button type="submit" class="btn-submit">提交预订</button>
                <div id="successMessage" class="feedback">
                    预订成功！我们会尽快与您确认，期待您的光临。
                </div>
            </form>

            <div class="info-container">
                <h3>餐厅信息</h3>
                <div class="info-box">
                    <p>地址：杭州市西湖区灵隐路118号</p>
                </div>
                <div class="info-box">
                    <p>电话：<strong>0571-88888888</strong></p>
                </div>
                <div class="info-box">
                    <p>为了确保您顺利用餐，建议提前预订。</p>
                </div>
                <div class="info-box">
                    <h4>营业时间</h4>
                    <table class="hours-table">
                        <tr><td>午餐</td><td>10:00 - 14:00</td></tr>
                        <tr><td>晚餐</td><td>17:00 - 22:00</td></tr>
                    </table>
                </div>
            </div>
        </div>
    </main>

    <script>
        document.getElementById('reservationForm').addEventListener('submit', function(e) {
            e.preventDefault();

            // 模拟提交过程
            const btn = this.querySelector('.btn-submit');
            const originalText = btn.innerText;

            btn.innerText = '提交中...';
            btn.disabled = true;

            setTimeout(() => {
                this.querySelector('.feedback').style.display = 'block';
                btn.innerText = originalText;
                btn.disabled = false;
                this.reset();
            }, 1500);
        });
    </script>

</body>
